package ro.leo.visual;
import android.app.*;import android.content.*;import android.bluetooth.*;import android.os.*;import android.net.Uri;import java.io.*;import java.util.*;
/** Explicit local fixture only; peer selected by the human. No recording or personal-file access. */
public final class BluetoothFileTrial extends Instrumentation {
 Bundle args;public void onCreate(Bundle b){args=b;start();}
 public void onStart(){Bundle out=new Bundle();try{Context c=getTargetContext();BluetoothAdapter adapter=BluetoothAdapter.getDefaultAdapter();String action=args.getString("action","status");if(action.equals("send")){String address=args.getString("device","");if(!BluetoothAdapter.checkBluetoothAddress(address))throw new IllegalArgumentException("Missing peer address");BluetoothDevice peer=adapter.getRemoteDevice(address);if(peer.getBondState()!=BluetoothDevice.BOND_BONDED)throw new IllegalStateException("Pair the selected phones first");File folder=new File(c.getCacheDir(),"shared");folder.mkdirs();File file=new File(folder,"leo-bluetooth-test.txt");BackupEngine.write(file,"LEO Bluetooth test - local fixture only.\n".getBytes("UTF-8"));ArrayList<Uri> uris=new ArrayList<Uri>();uris.add(LeoFileProvider.uri(c,file));BluetoothTransfers.send(c,address,uris,"text/plain");out.putString("result","QUEUED local test fixture");}else if(action.equals("status")){StringBuilder peers=new StringBuilder();for(BluetoothDevice d:adapter.getBondedDevices())peers.append(d.getName()).append(" ").append(d.getAddress()).append("\n");out.putString("peers",peers.toString());out.putString("transfers",BluetoothTransfers.run(c,"list",null).toString());}else throw new IllegalArgumentException("Unsupported trial action");}catch(Throwable e){out.putString("error",android.util.Log.getStackTraceString(e));}finish(out.containsKey("error")?Activity.RESULT_CANCELED:Activity.RESULT_OK,out);}
}
